  it("keeps the unknown zoom wide enough to show surrounding continents", () => {
    expect(UNKNOWN_ZOOM).toBeLessThan(ARTIST_ZOOM);
    expect(UNKNOWN_ZOOM).toBeLessThanOrEqual(3);
  });
});

